64	  /**
65	   * Every merge-side job now states the merge itself, because the gate it used
66	   * to inherit from `parse` is gone: parse runs for both outcomes of `closed`
67	   * so the rejection side can read its output (#267). A close that merged
68	   * nothing must not reach any of these three.
69	   */
70	  test("the merge-side jobs still test the merge themselves", () => {
71	    const all = jobs();
72	    for (const name of ["notify-parent", "reinvoke-origin-agent", "aggregate-sub-issues"]) {
73	      expect(all[name]?.if ?? "", `${name} must not run for a close that merged nothing`).toContain(
74	        "github.event.pull_request.merged == true",
75	      );
76	    }
77	  });
78	
79	  /**
80	   * The rejection half (#267): the close that merged nothing is returned to the
81	   * origin agent, and only that close -- the merged outcome belongs to the
82	   * three jobs above. It reads the issue from `parse` and decides everything
83	   * else itself, so `parse` is the one thing it waits on.
84	   */
85	  test("the close that merged nothing goes to dispatch-rejected, and only that close", () => {
86	    const rejected = jobs()["dispatch-rejected"];
87	    expect(rejected, "run `bun run synth` first").toBeDefined();
88	    expect(rejected?.if ?? "").toContain("github.event.pull_request.merged == false");
89	    expect(needs(rejected), "it reads the linked issue from parse").toContain("parse");
90	    expect(needs(rejected), "it uses nothing that resolution answers").not.toContain("resolve-parent");
91	  });
92	
93	  /**
94	   * The membership gate the reviewer required on #269, and the one test that
95	   * catches its absence: this is the only event-driven dispatch in the
96	   * repository that fires on an outcome an outside contributor can produce, so
97	   * without this test the boundary in `docs/work/boundaries.md` -- an agent
98	   * only starts when a repository member triggered it -- is a paragraph, not a
99	   * property. A fork's pull request closed unmerged must start nothing,
100	   * however its body is written.
101	   *
102	   * The signal is the head repository, not `author_association`: an agent's
103	   * pull request is authored by `github-actions[bot]`, association `NONE`, so
104	   * an association test would be false for every pull request the machinery
105	   * opened (the trap recorded on `atomaton-sub-issue-closed.wac.ts`).
106	   */
107	  test("dispatch-rejected fires only for a pull request whose head branch is this repository's", () => {
108	    const rejected = jobs()["dispatch-rejected"];
109	    expect(rejected, "run `bun run synth` first").toBeDefined();
110	    expect(rejected?.if ?? "").toContain("github.event.pull_request.head.repo.full_name == github.repository");
111	  });
